-- ExamGrind verified daily current-affairs desk: 7 November 2026.
-- Coverage window: substantive official releases published on 6 November, with one delivery recorded on 5 November and announced on 6 November.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-07-semicon-2-ecms-approvals$$, $$2026-11-07$$,
$$Semicon 2.0 application portal opens for three manufacturing pillars$$,
$$The government launched the Semicon 2.0 application portal for machines and materials, additional fabs, and ATMP/OSAT facilities. It also announced approval of 12 further Electronics Components Manufacturing Scheme applications, with projected investment of Rs 7,503 crore.$$,
$$This connects industrial policy, strategic electronics and domestic value chains. It is useful for questions that separate chip design, fabrication, packaging and the broader components ecosystem.$$,
$$Semicon 2.0 is the next phase of the India Semiconductor Mission. The portal makes applications live for pillars 2, 3 and 4; a portal launch is not itself approval of every future project. Fabs manufacture semiconductor devices, while ATMP/OSAT refers to assembly, testing, marking and packaging / outsourced semiconductor assembly and test. The accompanying ECMS approvals span components, supply-chain products and capital goods across seven States.$$,
$$Union Minister Ashwini Vaishnaw Launches Semicon 2.0 Web Application Portal and Announces 12 Approved Applicants under Electronics Components Manufacturing Scheme$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333716&lang=1&reg=3$$,
$$Ministry of Electronics and Information Technology / Press Information Bureau$$, $$2026-11-06$$,
$$["Applications opened for Semicon 2.0 pillars 2, 3 and 4.","Pillar 2 covers machines and materials; pillar 3 covers more fabs; pillar 4 strengthens ATMP/OSAT.","Twelve additional ECMS applications were approved with projected investment of Rs 7,503 crore.","ATMP/OSAT is a post-fabrication part of the semiconductor value chain, not chip fabrication itself."]$$::jsonb,
$$[{"question":"Which Semicon 2.0 pillar mentioned in the release relates to packaging and testing?","answer":"Pillar 4, which concerns further strengthening the ATMP/OSAT industry."}]$$::jsonb,
$${"title":"A semiconductor value chain","steps":["Materials and equipment support chip production.","Fabs manufacture semiconductor devices.","ATMP/OSAT handles assembly, testing and packaging.","Components and capital goods deepen domestic electronics manufacturing."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-telangana-amended-bharatnet$$, $$2026-11-07$$,
$$Telangana signs agreement for State-led Amended BharatNet rollout$$,
$$Digital Bharat Nidhi, Telangana, TRIICL, BSNL and T-Fiber signed an agreement to implement the Amended BharatNet Programme in Telangana under a State-led model. The approved Union financial support is Rs 3,189 crore for a scope of 12,769 Gram Panchayats.$$,
$$The announcement is a clear digital-governance and cooperative-federalism example. It tests BharatNet's rural-connectivity purpose and shows that a State-led implementation arrangement is still part of a Union-supported national programme.$$,
$$The Union Cabinet approved the Amended BharatNet Programme in August 2023 to upgrade, consolidate and extend rural broadband infrastructure. In Telangana, the plan includes converting 1,946 Phase I Gram Panchayats from linear to ring topology, covering 10,787 Phase II Gram Panchayats and including 36 newly created Gram Panchayats. Ring topology adds an alternate route and can improve network resilience compared with a simple linear arrangement.$$,
$$Agreement Signed between DBN (Digital Bharat Nidhi) - Department of Telecommunications; Government of Telangana; TRIICL; BSNL & T-Fibre for Implementation of Amended BharatNet Program in Telangana$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333683&lang=1&reg=3$$,
$$Department of Telecommunications / Press Information Bureau$$, $$2026-11-06$$,
$$["The Telangana agreement uses a State-led model under the Amended BharatNet Programme.","The programme scope is 12,769 Gram Panchayats in Telangana.","Approved Union financial support is Rs 3,189 crore.","The plan upgrades 1,946 Phase I Gram Panchayats from linear to ring topology."]$$::jsonb,
$$[{"question":"Does the Telangana agreement make BharatNet only a State scheme?","answer":"No. It implements the Union-approved Amended BharatNet Programme through a State-led model with Union financial support."}]$$::jsonb,
$${"title":"From backbone to rural digital services","steps":["BharatNet expands rural broadband infrastructure.","A State-led arrangement coordinates local rollout partners.","Resilient fibre topology strengthens last-mile connectivity.","Connectivity can support e-governance, telemedicine, education and payments."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-trai-interconnect-register-amendment$$, $$2026-11-07$$,
$$TRAI shifts telecom interconnect-agreement registration to an online system$$,
$$TRAI released the Register of Interconnect Agreements (Fourth Amendment) Regulations, 2026. Taking effect on 1 January 2027, the rules require service providers to register agreements and later modifications through TRAI's portal.$$,
$$This is a high-yield telecom-regulation item: it links the TRAI Act, interconnection between networks, regulatory transparency and digital public access. The rules govern the register of agreements; they do not create a new telecom operator licence.$$,
$$Interconnection is the technical and commercial arrangement that allows users on different telecom networks to communicate. The Register of Interconnect Agreements Regulations date to 1999. The amendment replaces physical-copy and diskette filing with online registration and text-searchable PDFs, while allowing online applications to inspect the register subject to the regulations. Existing agreements on the start date must be submitted within 15 days; new agreements or modifications have the same 15-day window after execution or modification.$$,
$$TRAI releases The Register of Interconnect Agreements (Fourth Amendment) Regulations, 2026$$,
$$https://trai.gov.in/notifications/press-release/trai-released-register-interconnect-agreements-fourth-amendment$$,
$$Telecom Regulatory Authority of India$$, $$2026-11-06$$,
$$["The amendment takes effect on 1 January 2027.","It moves registration of interconnect agreements to TRAI's online portal.","Electronic copies must be text-searchable PDFs.","Service providers generally have 15 days to submit existing, new or modified agreements under the stated timelines."]$$::jsonb,
$$[{"question":"What is an interconnect agreement for?","answer":"It records arrangements that let traffic pass between telecom networks so users of different providers can communicate."}]$$::jsonb,
$${"title":"How telecom interconnection is regulated","steps":["Separate service-provider networks need interconnection arrangements.","Providers enter into and modify agreements.","TRAI maintains a regulatory register under its statutory role.","Online filing and access improve record maintenance and transparency."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-omss-rice-target$$, $$2026-11-07$$,
$$Government raises the 2026-27 OMSS(D) rice-sale target to 50 lakh tonnes$$,
$$The Department of Food and Public Distribution doubled the 2026-27 target for rice sales under the Open Market Sale Scheme (Domestic) from 25 lakh metric tonnes to 50 lakh metric tonnes. The official release said 25 lakh metric tonnes had already been sold through e-auctions up to 31 October.$$,
$$The update links food-grain management, buffer stocks and price-stabilisation tools. It is useful for distinguishing an open-market intervention from procurement, a food-security entitlement or an MSP announcement.$$,
$$Under OMSS(D), food grains from public stocks are offered in the domestic open market, generally through e-auctions, to augment availability and help moderate prices. It works alongside, rather than replaces, the public distribution system. A lakh metric tonne is 100,000 metric tonnes; therefore 50 LMT equals five million metric tonnes.$$,
$$Government doubles OMSS (D) rice sale target from 25 LMT to 50 LMT for 2026-27; 25 LMT already sold through e-auctions up to 31 October 2026$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2332534&lang=1&reg=3$$,
$$Department of Food and Public Distribution / Press Information Bureau$$, $$2026-11-06$$,
$$["The 2026-27 OMSS(D) rice target was raised from 25 LMT to 50 LMT.","The release reports 25 LMT already sold through e-auctions by 31 October 2026.","OMSS(D) releases food grains from public stocks into the domestic open market.","One lakh metric tonne equals 100,000 metric tonnes."]$$::jsonb,
$$[{"question":"Is OMSS(D) the same as distributing free food-grain entitlement through the PDS?","answer":"No. OMSS(D) is an open-market sale mechanism using public stocks, typically through e-auctions; it is distinct from PDS entitlement delivery."}]$$::jsonb,
$${"title":"Public stocks and open-market supply","steps":["Government agencies hold food-grain stocks.","Market conditions can call for additional open-market availability.","OMSS(D) offers grain through e-auctions.","Higher availability can help moderate price pressure."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-nhai-mlff-toll-guidelines$$, $$2026-11-07$$,
$$NHAI issues design guidelines for barrier-less multi-lane free-flow tolling$$,
$$NHAI issued guidelines to standardise toll-plaza design and infrastructure for barrier-less Multi-Lane Free Flow tolling on four-lane and wider National Highways. The framework applies to future and under-construction projects, with different adoption routes depending on project stage.$$,
$$This is a useful infrastructure-governance brief because it connects NHAI, National Highway project design, technology-led tolling and road safety. It is about enabling infrastructure standards, not an announcement that every toll plaza has already become barrier-free.$$,
$$Multi-Lane Free Flow tolling aims to collect tolls without vehicles stopping at physical barriers. The guidelines cover layouts, lane configuration, gantries, lighting, signage and supporting facilities. Projects at the detailed project report stage must incorporate the design; projects already awarded or under construction are to adopt it through applicable contractual provisions. Electronic variable message signs help provide advance information to users.$$,
$$NHAI Guidelines to Standardise Design and Infrastructure for Multi-Lane Free Flow Tolling on Four-Lane and Above National Highways$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333654&lang=1&reg=3$$,
$$National Highways Authority of India / Press Information Bureau$$, $$2026-11-06$$,
$$["MLFF means Multi-Lane Free Flow tolling.","The guidelines address four-lane and wider National Highways.","They cover layout, lanes, gantries, road-safety features, signage and lighting.","DPR-stage projects incorporate the new design, while awarded or under-construction projects use applicable contractual provisions."]$$::jsonb,
$$[{"question":"Do the MLFF guidelines say that all existing toll plazas have immediately become barrier-free?","answer":"No. They standardise infrastructure for future and ongoing projects, with implementation depending on the project's stage and applicable provisions."}]$$::jsonb,
$${"title":"Designing a barrier-less toll zone","steps":["Highway projects need a tolling design.","MLFF uses infrastructure that can support tolling without stopping.","Standard layouts, gantries and signs create consistent road-user guidance.","Projects incorporate the requirements at the appropriate design or contract stage."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-sebi-settlement-regulations-commencement$$, $$2026-11-07$$,
$$SEBI's 2026 settlement regulations enter into force$$,
$$SEBI announced commencement of the SEBI (Settlement of Administrative and Civil Proceedings) Regulations, 2026. The regulations provide the framework through which specified proceedings may be settled in accordance with their terms.$$,
$$This is a core financial-regulation item. It helps students separate settlement from an adjudication on the merits: a settlement mechanism can resolve eligible proceedings under a regulator's framework, but it is not the same thing as an investor complaint process or an automatic exemption from securities law.$$,
$$SEBI regulates India's securities market and can pursue administrative or civil proceedings under the laws it administers. A settlement framework sets the process and conditions under which eligible matters may be resolved without continuing the proceeding to its ordinary conclusion. The regulations were notified earlier; the 6 November announcement records their commencement, so students should not confuse commencement with the date of the underlying notification.$$,
$$Commencement of SEBI (Settlement of Administrative and Civil Proceedings) Regulations, 2026$$,
$$https://www.sebi.gov.in/media-and-notifications/press-releases/nov-2026/commencement-of-sebi-settlement-of-administrative-and-civil-proceedings-regulations-2026_105680.html$$,
$$Securities and Exchange Board of India$$, $$2026-11-06$$,
$$["The update concerns SEBI's Settlement of Administrative and Civil Proceedings Regulations, 2026.","SEBI is India's securities-market regulator.","Settlement is a regulatory-process mechanism, not an investor-return product.","Commencement is distinct from the earlier notification of a regulation."]$$::jsonb,
$$[{"question":"What is the key distinction to retain about the 6 November SEBI update?","answer":"It announces commencement of the 2026 settlement regulations; it is not a new stock-market investment scheme or an individual enforcement order."}]$$::jsonb,
$${"title":"From proceeding to regulatory settlement","steps":["SEBI administers securities-market law.","A possible administrative or civil proceeding arises.","The settlement framework sets an eligibility-based route for resolution.","A settlement outcome operates under the regulations' conditions."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-bimstec-maritime-security-exercise$$, $$2026-11-07$$,
$$Maiden BIMSTEC Maritime Security Exercise concludes at Sri Vijaya Puram$$,
$$The first BIMSTEC Maritime Security Exercise concluded after harbour and sea phases held under the Andaman and Nicobar Command. The exercise brought regional representatives together for coordinated maritime activity and reinforced the group's Bay of Bengal cooperation agenda.$$,
$$This is relevant for international relations and maritime security because it combines BIMSTEC's regional role with India's Andaman and Nicobar Command. It is better read as an interoperability milestone than as a treaty or a new military alliance.$$,
$$BIMSTEC links seven Bay of Bengal and Himalayan countries: Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand. The Andaman and Nicobar Command is India's only operational tri-service command. The maiden exercise followed discussions on BIMSTEC maritime-security cooperation and included harbour-phase interaction followed by a sea phase; not every BIMSTEC member needs to deploy a warship for the grouping to be represented.$$,
$$Culmination of the Maiden BIMSTEC Maritime Security Exercise at Andaman and Nicobar Command$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333721&lang=1&reg=3$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-06$$,
$$["BIMSTEC has seven member countries.","The exercise was the maiden BIMSTEC Maritime Security Exercise.","It was held under the Andaman and Nicobar Command.","The Andaman and Nicobar Command is India's only operational tri-service command."]$$::jsonb,
$$[{"question":"Which regional grouping was the exercise associated with?","answer":"BIMSTEC, the seven-member Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation."}]$$::jsonb,
$${"title":"Regional maritime cooperation","steps":["BIMSTEC members share interests around the Bay of Bengal.","Maritime-security discussions identify common cooperation needs.","Harbour and sea phases build professional familiarity and coordination.","Interoperability can support a more secure and stable maritime environment."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-rahat-mitra-hadr-exercise$$, $$2026-11-07$$,
$$India and Myanmar begin inaugural tri-services HADR exercise Rahat Mitra$$,
$$India and Myanmar began their first bilateral tri-services Humanitarian Assistance and Disaster Relief exercise, Rahat Mitra, in Chennai on 5 November. The two-day exercise brought together more than 300 personnel and was coordinated by the Indian Navy.$$,
$$The item combines disaster management, defence diplomacy and India's Neighbourhood First policy. It is a practical example of HADR cooperation, not a combat operation or a mutual-defence treaty.$$,
$$HADR covers organised assistance and relief after disasters, where logistics, medical support, communications and joint coordination matter. A tri-services exercise involves the Army, Navy and Air Force. The release links the exercise to MAHASAGAR—Mutual and Holistic Advancement for Security and Growth Across Regions—and says it is intended to improve interoperability and experience-sharing between the two countries' defence forces.$$,
$$India and Myanmar Commence Inaugural Tri-Services Joint HADR Exercise Rahat Mitra$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333709&lang=1&reg=3$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-06$$,
$$["Rahat Mitra is India and Myanmar's maiden bilateral tri-services HADR exercise.","It was held at Chennai from 5 to 6 November 2026.","The exercise involved more than 300 personnel from both countries' three services.","The Indian Navy coordinated the exercise."]$$::jsonb,
$$[{"question":"What does HADR stand for in Exercise Rahat Mitra?","answer":"Humanitarian Assistance and Disaster Relief."}]$$::jsonb,
$${"title":"Why countries practise HADR together","steps":["A disaster can require rapid logistics and relief coordination.","Armed forces contribute transport, communications and medical support.","Joint exercises test common procedures and interoperability.","Shared practice can improve cross-border humanitarian response."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-amini-asw-shallow-water-craft$$, $$2026-11-07$$,
$$Indian Navy receives indigenous anti-submarine shallow-water craft Amini$$,
$$The Indian Navy received Amini, an indigenously designed and built Anti-Submarine Warfare Shallow Water Craft, from GRSE on 5 November. The Ministry of Defence says it carries more than 80% indigenous content and will strengthen anti-submarine, coastal-surveillance and mine-laying capability.$$,
$$This is a defence-indigenisation and maritime-security update. It tests the role of anti-submarine warfare and the difference between delivery to the Navy and later commissioning into service.$$,
$$Amini was designed and constructed by Garden Reach Shipbuilders and Engineers in accordance with Indian Register of Shipping classification rules. The craft is equipped with lightweight torpedoes, indigenous rocket launchers and sonars for underwater-threat detection and engagement. It is named after Amini Island in the Union Territory of Lakshadweep, continuing the name of an earlier Petya III-class anti-submarine warfare corvette decommissioned in 2002.$$,
$$Delivery of Amini, the Anti-Submarine Warfare Shallow Water Craft$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333404&lang=1&reg=3$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-06$$,
$$["Amini is an Anti-Submarine Warfare Shallow Water Craft.","It was designed and built by GRSE with over 80% indigenous content, according to the release.","The ship is named after Amini Island in Lakshadweep.","Delivery is distinct from a later commissioning announcement."]$$::jsonb,
$$[{"question":"Which public-sector shipbuilder designed and built Amini?","answer":"Garden Reach Shipbuilders and Engineers (GRSE), Kolkata."}]$$::jsonb,
$${"title":"A shallow-water ASW capability","steps":["Domestic shipbuilding creates the naval platform.","Sonars help detect underwater threats.","Torpedoes and rocket launchers support anti-submarine operations.","The craft adds to coastal surveillance and maritime-security capability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-07-startup-india-i-stem-integration$$, $$2026-11-07$$,
$$Startup India and I-STEM portals are linked to widen research-infrastructure access$$,
$$The Office of the Principal Scientific Adviser and DPIIT launched API integration between the Startup India portal and I-STEM. The integration helps DPIIT-recognised startups discover scientific, testing and prototyping facilities listed on the national I-STEM platform.$$,
$$This is an innovation-policy item that links startups with shared public and institutional research infrastructure. It is important not to overread it as guaranteed access: host institutions will continue to assess individual requests.$$,
$$I-STEM is the Indian Science, Technology and Engineering Facilities Map, intended to improve discovery and use of research infrastructure. The release lists 31,540 equipment items across 4,044 registered institutions as of 6 November. API interoperability can streamline information exchange and recognition-status verification; a proposed later phase would add single sign-on. Access remains subject to technical suitability, availability, charges, safety requirements and institutional permission.$$,
$$Office of the Principal Scientific Adviser and DPIIT Launches API Integration between Startup India and I-STEM Portals to Strengthen Access to National Research Infrastructure$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2333736&lang=1&reg=3$$,
$$Office of the Principal Scientific Adviser / Press Information Bureau$$, $$2026-11-06$$,
$$["I-STEM stands for Indian Science, Technology and Engineering Facilities Map.","The integration links DPIIT's Startup India portal with I-STEM.","I-STEM listed 31,540 equipment items across 4,044 registered institutions on 6 November 2026.","Host institutions still decide individual access requests based on suitability, availability and applicable conditions."]$$::jsonb,
$$[{"question":"Does portal integration automatically give every recognised startup unrestricted use of laboratory equipment?","answer":"No. It improves discovery and onboarding, but host institutions continue to evaluate requests and apply their conditions."}]$$::jsonb,
$${"title":"From startup need to shared facility","steps":["A DPIIT-recognised startup needs specialised testing or prototyping.","Portal integration helps it discover listed research infrastructure.","The startup requests access from the host institution.","The host assesses availability, safety, charges and technical suitability."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = now(),
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-07-semicon-2-ecms-approvals$$,
$$2026-11-07-telangana-amended-bharatnet$$,
$$2026-11-07-trai-interconnect-register-amendment$$,
$$2026-11-07-omss-rice-target$$,
$$2026-11-07-nhai-mlff-toll-guidelines$$,
$$2026-11-07-sebi-settlement-regulations-commencement$$,
$$2026-11-07-bimstec-maritime-security-exercise$$,
$$2026-11-07-rahat-mitra-hadr-exercise$$,
$$2026-11-07-amini-asw-shallow-water-craft$$,
$$2026-11-07-startup-india-i-stem-integration$$
)
and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict (brief_id, exam_id) do nothing;
